# Viva — slot D7 (part A): nevi & hamartomas (9 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — neonatal/naevi chapter (Becker's naevus,
# naevus of Ota, naevus sebaceous, Kamino bodies, halo naevus), tumour syndromes; facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"
ABCDE = ["Asymmetry, Border irregularity, Colour variegation, Diameter >6 mm, Evolution (change in size/shape/colour, symptoms) — plus 'ugly duckling' sign (lesion different from the patient's other naevi)", "Glasgow 7-point checklist: major — change in size, shape, colour; minor — diameter ≥7 mm, inflammation, oozing/bleeding, altered sensation"]

D = [
dict(case="Acquired melanocytic nevus (mole)", src=f"{PYQ}; {IA} (Melanocytic naevi; melanoma)",
 qa=[
 ("What is an acquired melanocytic naevus?", ["Benign proliferation of naevus cells (melanocytes) in nests, appearing after 6 months of age, increasing in childhood/young adulthood (peak in 3rd decade) and regressing in old age; number linked to sun exposure in childhood and genetics; fewer in dark skin"]),
 ("Classify by histological level (life cycle).", ["Junctional: flat, uniformly brown, nests at dermo-epidermal junction (children)", "Compound: slightly raised brown papule, junctional + dermal nests", "Intradermal: dome-shaped skin-coloured/light-brown papule, often with hairs, dermal nests only with maturation (smaller, neurotised cells deeper) — adults, face", "Special types: blue naevus (dermal dendritic melanocytes — blue due to Tyndall effect), Spitz naevus, halo naevus, dysplastic (atypical/Clark's) naevus, recurrent naevus, acral naevus (parallel furrow pattern), Meyerson naevus (eczematous halo), combined naevus"]),
 ("What is a dysplastic (atypical) naevus and the atypical mole syndrome?", ["Clinically atypical naevus: ≥5 mm, irregular/ill-defined border, variegated colour, flat component ('fried-egg'); histology — architectural disorder (bridging, lentiginous growth, shouldering), cytological atypia, lamellar fibroplasia", "Atypical mole syndrome / FAMMM (familial atypical multiple mole melanoma): >50–100 naevi, several atypical, family history of melanoma — CDKN2A (p16) mutations (also pancreatic cancer risk); lifelong surveillance with total body photography and dermoscopy"]),
 ("Write a short note on Kamino bodies (PYQ).", ["Eosinophilic, PAS-positive, diastase-resistant, globular hyaline bodies (basement membrane material — collagen IV/laminin) at the dermo-epidermal junction above the nests in Spitz naevus; seen in ~60–80% — favour Spitz over melanoma when numerous and confluent"]),
 ("What is a Spitz naevus?", ["Benign melanocytic naevus of spindle and/or epithelioid cells, children and young adults; dome-shaped pink-red or brown papule on face/legs growing quickly then stabilising; dermoscopy — starburst pattern (pigmented Reed naevus) or dotted vessels (pink)", "Histology: symmetric, well-circumscribed, maturation, Kamino bodies, clefts around junctional nests, epidermal hyperplasia", "Atypical Spitz tumours — uncertain potential; excision recommended in adults/atypical lesions"]),
 ("Dermoscopy of benign naevi.", ["Reticular (network), globular, homogeneous (blue naevus), starburst (Spitz/Reed), parallel furrow (acral), peripheral rim of globules (growing naevus in children)", "Melanoma-specific structures: atypical network, negative network, irregular streaks, irregular dots/globules, blue-white veil, regression structures, atypical vessels, parallel ridge pattern (acral), shiny white lines"]),
 ("What are the ABCDE warning signs?", ABCDE),
 ("Risk factors for melanoma related to naevi.", ["Number of common naevi (>100), atypical naevi (≥5), large congenital naevi, family history (CDKN2A, CDK4, BAP1, MITF), fair skin, sunburns, immunosuppression; in India, acral lentiginous melanoma is commonest (soles, nails — not UV-related)"]),
 ("Management.", ["Benign naevi — reassurance; sun protection; monitor with photographs/dermoscopy", "Excision biopsy (narrow 2 mm margins, full thickness) for any suspicious lesion; do not shave/laser suspicious pigmented lesions", "Cosmetic removal: shave excision, punch, radiofrequency (only after confirming benign)", "Teach self-examination; total-body photography for many/atypical naevi"]),
 ],
 spot=["Ugly duckling — biopsy", "Kamino bodies — Spitz naevus", "Acral lentiginous melanoma — commonest in India"]),

dict(case="Becker's nevus", src=f"{PYQ}; {IA} (Becker's naevus)",
 qa=[
 ("Write a short note on Becker's naevus (PYQ).", ["Acquired-appearing (often congenital but noticed around adolescence) unilateral, large, irregular, light- to dark-brown patch with geographic border on shoulder, upper chest, scapula, upper arm, with hypertrichosis (coarse dark hair) appearing later; men 4–6× more (androgen-dependent — increased androgen receptors)", "A smooth-muscle hamartoma component (Becker's naevus = hamartoma of epidermis, melanocytes, smooth muscle, hair)", "Postzygotic ACTB (β-actin) mutations"]),
 ("Clinical features.", ["Patch becomes darker and thicker after sun exposure/puberty; acneiform lesions within, pseudo-Darier's sign (smooth muscle — transient elevation/piloerection on rubbing); usually single; may be multiple or bilateral"]),
 ("What is Becker's naevus syndrome?", ["Becker's naevus with ipsilateral hypoplasia of breast/areola (most common), pectoralis major, limb shortening, scoliosis, spina bifida, supernumerary nipples, lipoatrophy — included in the epidermal naevus syndromes"]),
 ("Histopathology.", ["Mild acanthosis with elongated flat-bottomed pigmented rete ridges (basal hyperpigmentation), increased melanin with normal or slightly increased melanocytes, increased smooth muscle bundles in the dermis (smooth muscle hamartoma overlap), prominent hair follicles"]),
 ("Differential diagnosis.", ["Café-au-lait macule (no hair, earlier onset), congenital melanocytic naevus (raised, darker, nested), smooth muscle hamartoma (congenital, pseudo-Darier's), nevus spilus, plexiform neurofibroma, McCune–Albright CALM, PIH, segmental pigmentation"]),
 ("Management.", ["Reassurance — benign; no malignant potential", "Cosmetic: Q-switched/picosecond lasers (pigment — variable, recurrence), fractional lasers, long-pulsed alexandrite/diode laser hair removal (addresses hypertrichosis and can lighten pigment); camouflage", "Topical flutamide (anti-androgen) for breast hypoplasia reported; spironolactone for associated hypoplasia (reports)"]),
 ],
 spot=["Unilateral brown patch with coarse hair on the shoulder of a young man — Becker's naevus", "Ipsilateral breast hypoplasia — Becker's naevus syndrome"]),

dict(case="Congenital melanocytic nevus", src=f"{PYQ}; {IA} (Congenital melanocytic naevi)",
 qa=[
 ("Define congenital melanocytic naevus (CMN).", ["Benign melanocytic proliferation present at birth or appearing within the first 6 months ('tardive' up to 2 years); ~1% of newborns; NRAS mutations (Q61) in most large CMN, BRAF in small"]),
 ("Classify by projected adult size.", ["Small <1.5 cm, medium 1.5–20 cm (M1 1.5–10, M2 >10–20), large 20–40 cm, giant >40 cm (projected adult size — head ×1.7, trunk/limbs ×3 growth from infancy)", "Satellite naevi counted (≤20, 20–50, >50) — more satellites → higher risk of neurocutaneous melanosis"]),
 ("Clinical features.", ["Brown to black, often raised, mammillated or verrucous surface, hypertrichosis, may have nodules (proliferative nodules — usually benign), variegated colour; large CMN in 'bathing trunk' or 'garment' distribution with satellites", "Large/giant CMN may cause pruritus, xerosis, erosions; colour may lighten with time"]),
 ("Risks associated with large CMN.", ["Melanoma: lifetime ~2–5% for large/giant (higher in giant >40 cm with many satellites); can arise in deep dermis/subcutis or CNS, often in first 5 years; small/medium — <1% lifetime, mainly after puberty at the dermo-epidermal junction", "Neurocutaneous melanosis: melanocytes in leptomeninges — hydrocephalus, seizures, developmental delay, CNS melanoma; screen with MRI brain and spine (ideally before 6 months of age) in large CMN or >20 satellite naevi"]),
 ("Histopathology.", ["Naevus cells extending deep into reticular dermis and subcutis, around/within adnexa (hair follicles, eccrine ducts), nerves and vessels, splaying between collagen bundles in single-file arrangement — distinguishes from acquired naevi"]),
 ("Differential diagnosis.", ["Café-au-lait macule, Becker's naevus, nevus spilus, epidermal naevus, Mongolian spot, plexiform neurofibroma, smooth muscle hamartoma, mastocytoma, nevus sebaceous"]),
 ("Management.", ["Individualised: clinical photographs and regular examination (palpation for nodules), dermoscopy; biopsy any new nodule, ulcer or rapid change", "Small/medium: observation or elective excision for cosmetic reasons or difficult-to-monitor sites (scalp)", "Large/giant: staged excision with tissue expanders, flaps, grafts (does not eliminate melanoma risk completely); curettage in neonatal period, dermabrasion, lasers (cosmetic; may hamper monitoring)", "MRI CNS screening as above; psychosocial support; trametinib (MEK inhibitor) under study"]),
 ],
 spot=["Large hairy pigmented naevus with satellites — giant CMN; MRI for neurocutaneous melanosis", "Projected adult size >20 cm = large"]),

dict(case="Epidermal nevus / ILVEN", src=f"{PYQ}; {IA} (Epidermal naevi)",
 qa=[
 ("What is an epidermal naevus?", ["Hamartoma of the epidermis and/or adnexal structures due to postzygotic (mosaic) mutation, following Blaschko's lines; present at birth or early childhood (~1 in 1000)", "Types: keratinocytic (verrucous epidermal naevus — FGFR3, PIK3CA, HRAS; epidermolytic — KRT1/10), organoid (nevus sebaceous — HRAS/KRAS, nevus comedonicus — NEK9, Becker's naevus, porokeratotic eccrine naevus), ILVEN (inflammatory)"]),
 ("Describe verrucous epidermal naevus.", ["Linear, skin-coloured to brown, velvety then warty papules coalescing into plaques along Blaschko's lines, usually unilateral on trunk/limbs; localised or systematised (ichthyosis hystrix — bilateral extensive)"]),
 ("What is ILVEN?", ["Inflammatory linear verrucous epidermal naevus: persistent, intensely itchy, erythematous, scaly, psoriasiform papules and plaques in a linear Blaschkoid pattern, usually on the lower limb/buttock, onset in early childhood (girls), very resistant to therapy", "Histology: psoriasiform hyperplasia with alternating orthokeratosis over hypergranulosis and parakeratosis over agranulosis; dermal lymphocytes", "Differential: linear psoriasis (responds to antipsoriatics, other psoriasis features, Munro microabscesses), lichen striatus (self-limiting, not itchy), linear LP, linear porokeratosis, linear DLE"]),
 ("What is epidermal naevus syndrome?", ["Epidermal naevus with extracutaneous anomalies of CNS (seizures, intellectual disability, hemimegalencephaly), eye (colobomas, lipodermoids), skeleton (hemihypertrophy, kyphoscoliosis, vitamin D-resistant rickets — FGF23 hypophosphataemia), urogenital and cardiovascular systems", "Includes Schimmelpenning (nevus sebaceous), Proteus, CHILD, phacomatosis pigmentokeratotica, Becker's naevus syndrome, nevus comedonicus syndrome"]),
 ("Discuss principles of mosaicism (PYQ).", ["Mosaicism = two or more genetically distinct cell populations derived from one zygote (postzygotic mutation)", "Patterns of cutaneous mosaicism (Happle): Blaschko's lines (narrow and broad bands), checkerboard, phylloid (leaf-like — trisomy 13), patchy without midline separation (large CMN), lateralisation (CHILD)", "Type 1 segmental (heterozygous postzygotic mutation in a dominant disorder — segmental NF1) vs type 2 segmental (loss of heterozygosity — severe segment superimposed on generalised disease); gonadal mosaicism → transmission of generalised disease to offspring (e.g. epidermolytic naevus → epidermolytic ichthyosis child)", "Lethal autosomal dominant mutations survive only in mosaic state (Proteus — AKT1, McCune–Albright — GNAS, Schimmelpenning — HRAS)"]),
 ("Management.", ["Topical keratolytics, retinoids, calcipotriol, steroids (ILVEN — potent steroids/occlusion, tacrolimus, dithranol) — usually poor response", "Destructive: full-thickness surgical excision (definitive; deep enough to avoid recurrence), CO2/Er:YAG laser ablation, dermabrasion, cryotherapy (recurrence common if superficial)", "Oral acitretin for extensive systematised naevi; examine for associated anomalies"]),
 ],
 spot=["Linear warty plaque along Blaschko's lines from birth — verrucous epidermal naevus", "Itchy psoriasiform linear plaque on leg of a young girl — ILVEN"]),

dict(case="Halo nevus", src=f"{PYQ}; {IA} (Halo naevus)",
 qa=[
 ("Discuss halo naevus — pathophysiology (PYQ).", ["Melanocytic naevus (usually compound or intradermal) surrounded by a symmetrical round/oval depigmented halo, due to immune-mediated (CD8+ T-cell) destruction of naevus cells and surrounding melanocytes — Sutton's naevus / leucoderma acquisitum centrifugum", "Children and adolescents, trunk (back) commonest; may be multiple"]),
 ("Stages.", ["Stage I: pigmented naevus with halo; II: naevus becomes pink/lighter; III: naevus disappears leaving a depigmented macule; IV: repigmentation of the halo (may take years)"]),
 ("Associations.", ["Vitiligo (in ~20–50% of patients with halo naevi; multiple halo naevi increase vitiligo risk), autoimmune thyroid disease, Turner syndrome, melanoma (halo around melanoma or distant halo naevi in metastatic melanoma — especially in adults; immunotherapy-associated leucoderma)"]),
 ("Histopathology.", ["Dense lymphocytic infiltrate (CD8 T cells, macrophages) intermingled with naevus cells in the dermis ('naevus being destroyed'), loss of melanocytes in the halo epidermis"]),
 ("When should a halo naevus be biopsied?", ["Atypical central naevus (asymmetry, irregular colour, ulceration), eccentric/irregular halo, onset in adulthood (>40 y), history of melanoma, change in the central lesion — to exclude melanoma"]),
 ("Differential diagnosis.", ["Melanoma with regression/halo, vitiligo around naevus, halo around other lesions (blue naevus, Spitz, seborrhoeic keratosis, molluscum, neurofibroma, BCC), post-inflammatory hypopigmentation"]),
 ("Management.", ["Reassurance — benign, spontaneous course; full skin and eye examination; photoprotection of halo", "No treatment needed; excision only if atypical; screen for vitiligo/thyroid"]),
 ],
 spot=["Symmetric depigmented ring around a mole on a child's back — halo naevus", "Atypical halo in adult — biopsy (melanoma)"]),

dict(case="Nevus comedonicus", src=f"{PYQ}; {IA} (Epidermal naevi — organoid)",
 qa=[
 ("What is nevus comedonicus?", ["Rare organoid epidermal (follicular) naevus with clusters of dilated follicular openings plugged with dark keratin (comedo-like), arranged in a linear/Blaschkoid band, usually unilateral on face, neck, trunk or upper limbs; present at birth or childhood; NEK9 mosaic mutation"]),
 ("Clinical variants.", ["Non-inflammatory (comedones only)", "Inflammatory: cysts, pustules, abscesses, scarring (acne-like) — often from puberty", "Nevus comedonicus syndrome: with CNS (seizures), skeletal (scoliosis, polydactyly), ocular (cataract) anomalies — epidermal naevus syndrome"]),
 ("Histopathology.", ["Wide, deep invaginations of epidermis filled with laminated keratin; rudimentary hair shafts or sebaceous lobules; follicular rupture with inflammation in inflammatory type"]),
 ("Differential diagnosis.", ["Acne vulgaris/comedonal (not linear), chloracne, Favre–Racouchot syndrome (solar comedones in elderly), familial dyskeratotic comedones, Dowling–Degos (comedo-like papules), linear porokeratosis, porokeratotic eccrine naevus (palms/soles), verrucous epidermal naevus"]),
 ("Management.", ["Comedo extraction, topical retinoids, keratolytics (salicylic, lactic acid), ammonium lactate", "Inflammatory: oral antibiotics, isotretinoin", "Definitive: surgical excision; dermabrasion, CO2/Er:YAG laser, electrocautery"]),
 ],
 spot=["Linear cluster of comedones on a child's neck — nevus comedonicus"]),

dict(case="Nevus of Ota / Ito / Hori", src=f"{PYQ}; {IA} (Dermal melanocytoses)",
 qa=[
 ("Write a short note on nevus of Ota (PYQ).", ["Dermal melanocytosis (oculodermal melanocytosis) with blue-grey to brown mottled patch in the distribution of the 1st and 2nd branches of the trigeminal nerve (forehead, temple, periorbital, malar), unilateral in ~90%; ipsilateral scleral (blue-grey) and ocular involvement in ~2/3", "Asian and Indian women more; onset at birth (50%) or around puberty (second peak); GNAQ/GNA11 mutations", "Mucosa (palate, nasal), tympanic membrane may be involved"]),
 ("Tanino classification.", ["Type I mild (Ia orbital, Ib zygomatic), II moderate (V1+V2 area), III intensive (scalp, forehead, nose), IV bilateral"]),
 ("Complications.", ["Glaucoma (ipsilateral — regular eye checks), uveal/ choroidal melanoma (especially in white patients), CNS melanoma (rare), sensorineural hearing loss; associated with Sturge–Weber/Klippel–Trenaunay (phakomatosis pigmentovascularis)"]),
 ("What is nevus of Ito and Hori's naevus?", ["Nevus of Ito: same dermal melanocytosis in the distribution of posterior supraclavicular and lateral cutaneous brachial nerves (shoulder, supraclavicular, scapula, upper arm)", "Hori's naevus (acquired bilateral naevus of Ota-like macules — ABNOM): acquired in middle-aged Asian women, bilateral blue-brown speckled macules on malar areas, forehead, eyelids; no ocular/mucosal involvement; often misdiagnosed as melasma"]),
 ("Histopathology.", ["Elongated, dendritic, pigmented melanocytes scattered among collagen bundles in the upper and mid dermis (dermal melanocytes) — superficial, deep or diffuse types; epidermis normal"]),
 ("Differential diagnosis.", ["Melasma (bilateral brown, no blue-grey or eye involvement), Mongolian spot (sacral, fades), blue naevus, lichen planus pigmentosus, drug pigmentation (minocycline), PIH, port-wine stain (early), ecchymosis"]),
 ("Management.", ["Q-switched lasers (Nd:YAG 1064 nm — preferred in dark skin, alexandrite 755 nm, ruby 694 nm) or picosecond lasers — multiple sessions (5–10) 2–3 months apart; excellent response (selective photothermolysis of dermal melanin); risk of PIH/hypopigmentation, recurrence", "Ophthalmology review (glaucoma, melanoma) at baseline and periodically; camouflage"]),
 ],
 spot=["Unilateral blue-grey patch on V1/V2 with scleral pigmentation — nevus of Ota", "Q-switched Nd:YAG laser", "Bilateral acquired malar blue-brown macules — Hori's naevus"]),

dict(case="Nevus sebaceous (of Jadassohn)", src=f"{PYQ}; {IA} (Organoid naevi)",
 qa=[
 ("Write a short note on nevus sebaceous (PYQ).", ["Congenital hamartoma of the pilosebaceous–apocrine unit and epidermis (organoid epidermal naevus) — postzygotic HRAS/KRAS mutations; scalp (commonest), face, neck; ~0.3% of newborns"]),
 ("Describe the three stages (clinical and histological).", ["Infancy/childhood: smooth, slightly raised, yellow-orange, waxy, hairless (alopecic) oval/linear plaque on the scalp; histology — immature hair follicles, small sebaceous glands", "Puberty (hormonal): becomes verrucous, thicker, more yellow, pebbly/cobblestoned; histology — papillomatous epidermal hyperplasia, abundant mature sebaceous glands, ectopic apocrine glands, absent terminal hairs", "Adulthood: development of secondary adnexal neoplasms — trichoblastoma (commonest), syringocystadenoma papilliferum, sebaceoma, apocrine tumours; BCC (true BCC uncommon, ~1%), rarely SCC, adnexal carcinomas"]),
 ("What is Schimmelpenning syndrome (linear nevus sebaceous syndrome)?", ["Extensive nevus sebaceous with CNS (seizures, intellectual disability, hemimegalencephaly), ocular (colobomas, lipodermoids), skeletal (hypophosphataemic rickets), cardiac and urogenital anomalies; part of epidermal naevus syndromes"]),
 ("Differential diagnosis.", ["Aplasia cutis congenita (atrophic/membranous, not waxy), epidermal naevus, juvenile xanthogranuloma, mastocytoma, solitary trichoepithelioma, syringocystadenoma papilliferum, congenital triangular alopecia, juvenile xanthogranuloma"]),
 ("Management.", ["Observation with periodic examination vs prophylactic full-thickness surgical excision (often before puberty for cosmetic reasons/alopecia, and because secondary tumours may arise) — decision individualised (malignancy risk lower than once thought)", "Biopsy any new nodule or ulcer; CO2 laser/PDT for those unsuitable for surgery (risk of recurrence)"]),
 ],
 spot=["Yellow-orange waxy hairless plaque on scalp of a newborn — nevus sebaceous", "Trichoblastoma is the commonest secondary tumour"]),

dict(case="Nevus spilus (speckled lentiginous nevus)", src=f"{PYQ}; {IA} (Melanocytic naevi)",
 qa=[
 ("What is nevus spilus?", ["Speckled lentiginous naevus: a light-brown café-au-lait-like background patch studded with darker brown-black macules or papules (lentigines, junctional/compound naevi, sometimes blue or Spitz naevi); present at birth or appearing in childhood; considered a type of congenital melanocytic naevus (HRAS/BRAF mosaic)"]),
 ("Clinical types.", ["Macular type (flat speckles — lentigines/junctional naevi) and papular type (raised speckles — compound/dermal naevi)", "Size from small to giant/segmental (zosteriform)", "Phacomatosis pigmentokeratotica (papular nevus spilus + nevus sebaceous — HRAS), phacomatosis pigmentovascularis (with vascular malformation), speckled lentiginous naevus syndrome (neurological anomalies)"]),
 ("Malignant potential.", ["Low; melanoma reported especially in large/giant or segmental lesions and the papular type — monitor speckles for change; biopsy atypical components"]),
 ("Differential diagnosis.", ["Café-au-lait macule with lentigines (NF1/Legius — axillary freckling), agminated lentigines/naevi, congenital melanocytic naevus, Becker's naevus, partial unilateral lentiginosis, LEOPARD/Noonan"]),
 ("Management.", ["Observation with photographs and dermoscopy; excision of any atypical speckle", "Cosmetic: Q-switched/picosecond lasers (background and speckles), excision of small lesions; caution — laser may complicate monitoring"]),
 ],
 spot=["Café-au-lait patch with dark speckles — nevus spilus"]),
]
